// Adversarial test suite for the formula function-name extractors.
//
// canispreadsheet.com has TWO extraction code paths and they must agree:
//   1. the Migration Audit's  XlsxAudit.extractFunctions()  (audit.js), fed by
//      the client-side .xlsx parser;
//   2. the compatibility checker's  funcs()  — inline JS generated by
//      site/build_site.py into docs/checker.html, fed by a paste box.
// This file loads BOTH (the checker one straight out of the built
// docs/checker.html, so it tests what actually ships) and runs the same case
// table through each.
//
// Usage: node test-adversarial.mjs   (Node 18+, no deps)
// The functional suite is test.mjs; this one is the hostile-input suite.

import fs from 'node:fs';
import path from 'node:path';
import url from 'node:url';
import { createRequire } from 'node:module';

const here = path.dirname(url.fileURLToPath(import.meta.url));
const require = createRequire(import.meta.url);
const X = require(path.join(here, 'audit.js'));

/* ---------- load the checker's funcs() out of the BUILT page ---------- */
// If this fails after editing build_site.py, run `python3 build_site.py`.
const checkerPath = path.join(here, '..', '..', 'docs', 'checker.html');
const checkerHtml = fs.readFileSync(checkerPath, 'utf8');
const START = 'function splitLits(';
const END = 'return [...set]; }';
const s0 = checkerHtml.indexOf(START);
const s1 = checkerHtml.indexOf(END, s0);
if (s0 < 0 || s1 < 0) {
  console.error('FATAL: could not find funcs() in docs/checker.html — rebuild the site.');
  process.exit(1);
}
const checkerSrc = checkerHtml.slice(s0, s1 + END.length);
// eslint-disable-next-line no-new-func
const checkerFuncs = new Function(checkerSrc + '\nreturn funcs;')();

let pass = 0, fail = 0;
function ok(cond, label) {
  if (cond) { pass++; console.log('  ok  ' + label); }
  else { fail++; console.log('  FAIL ' + label); }
}
const norm = (a) => JSON.stringify([...new Set(a)].sort());
function eqSet(actual, expected, label) {
  const good = norm(actual) === norm(expected);
  if (!good) {
    console.log('       expected: ' + norm(expected) + '\n       actual:   ' + norm(actual));
  }
  ok(good, label);
}

/* ================= the shared adversarial case table =================
 * [formula, expected function set, label]
 * Every case runs through BOTH extractors and must produce the same set.
 */
const CASES = [
  /* --- function-like text inside string literals --- */
  ['=IF(A1="SUM(", 1, 0)', ['IF'], 'unbalanced paren inside a string literal'],
  ['="COUNT(A1)"', [], 'a whole formula that is just a string literal'],
  ['=CONCAT("x(", "y)")', ['CONCAT'], 'parens split across two string literals'],
  ['=SUBSTITUTE(A1,"""","\'")', ['SUBSTITUTE'], 'escaped "" quote inside a literal'],
  ['=IF(A1="he said ""SUM(1)""",TRUE(),FALSE())', ['IF', 'TRUE', 'FALSE'],
    'nested escaped quotes around a fake call'],

  /* --- structured (table) references --- */
  ['=SUM(Table1[@[Unit Price]])', ['SUM'], 'structured ref: this-row + spaced column'],
  ['=SUM(Table1[[#Totals],[Amount]])', ['SUM'], 'structured ref: #Totals item specifier'],
  ['=COUNTA(Table1[Col])', ['COUNTA'], 'structured ref: plain column'],
  ['=SUMIFS(Table1[Amount],Table1[Region],"North")', ['SUMIFS'], 'structured refs + criteria string'],

  /* --- dynamic arrays: spill and implicit intersection --- */
  ['=@A1:A3', [], 'implicit-intersection operator alone'],
  ['=A1#', [], 'spill operator alone'],
  ['=SUM(A1#)', ['SUM'], 'spill operator as an argument'],
  ['=_xlfn.SINGLE(A1:A3)', ['SINGLE'], '@ as stored in xlsx (_xlfn.SINGLE)'],
  ['=_xlfn.ANCHORARRAY(A1)', ['ANCHORARRAY'], '# as stored in xlsx (_xlfn.ANCHORARRAY)'],

  /* --- the _xlfn. / _xlws. storage prefixes, every form --- */
  ['=_xlfn.XLOOKUP(A1,B:B,C:C)', ['XLOOKUP'], '_xlfn. prefix'],
  ['=_xlfn._xlws.FILTER(A:A,B:B)', ['FILTER'], '_xlfn._xlws. prefix'],
  ['=_XLFN._XLWS.SORT(A:A)', ['SORT'], 'uppercase _XLFN._XLWS. prefix'],
  ['=_xlfn.TEXTSPLIT(A1,",")', ['TEXTSPLIT'], '_xlfn. prefix + string argument'],
  ['=IFERROR(_xlfn.XLOOKUP(A1,B:B,C:C),0)', ['IFERROR', 'XLOOKUP'], 'prefixed call nested in a plain one'],

  /* --- LET / LAMBDA: parameter names that look like functions --- */
  ['=LET(sum,SUM(A1:A3),max,MAX(A1:A3),sum+max)', ['LET', 'SUM', 'MAX'],
    'LET names shadowing real function names'],
  ['=LET(x,1,y,2,x+y)', ['LET'], 'LET with plain names yields only LET'],
  ['=LAMBDA(x,y,x+y)(1,2)', ['LAMBDA'], 'directly-invoked LAMBDA: )( is not a call'],
  ['=MAP(A1:A3,LAMBDA(v,v*2))', ['MAP', 'LAMBDA'], 'lambda helper + LAMBDA'],
  ['=REDUCE(0,A1:A3,LAMBDA(acc,v,acc+v))', ['REDUCE', 'LAMBDA'], 'REDUCE with an accumulator name'],

  /* --- sheet names / defined names that contain function-like tokens --- */
  ["='SUM Sheet'!A1", [], 'quoted sheet name containing a function name'],
  ['=Sheet1!A1+MAX(1,2)', ['MAX'], 'unquoted sheet ref + a real call'],
  ["=SUM('My Data (2024)'!A1:A5)", ['SUM'], 'quoted sheet name containing parentheses'],
  ["=SUM('Ünïcode (x)'!A1:A2)", ['SUM'], 'non-ASCII quoted sheet name with parentheses'],
  ["='Bob''s (old) Data'!A1", [], "sheet name with an escaped '' apostrophe and parens"],
  ['=MyNamedRange*2', [], 'defined name, no call'],
  ['=IF2+1', [], 'defined name that starts with a function name'],
  ['=MYSUM(A1)', ['MYSUM'], 'defined name ending in a function name is one whole token'],

  /* --- cross-workbook references --- */
  ['=SUM([Book1.xlsx]Sheet1!A1:A3)', ['SUM'], 'cross-workbook ref, unquoted'],
  ["='[Book1.xlsx]Sheet1'!A1", [], 'cross-workbook ref, quoted'],

  /* --- whitespace --- */
  ['=SUM(\n A1:A3 \n)', ['SUM'], 'newlines inside the argument list'],
  ['=SUM\t(A1:A3)', ['SUM'], 'tab between name and paren'],
  ['=IF(\r\n A1>0,\r\n SUM(B1:B3),\r\n 0)', ['IF', 'SUM'], 'CRLF-formatted formula'],

  /* --- unicode --- */
  ['=SUM(A1:A3)&"→"&TEXT(1,"0")', ['SUM', 'TEXT'], 'non-ASCII text in a string literal'],
  ['=Größe(A1)', [], 'non-ASCII name must not yield a bogus ASCII tail'],
  ['=ПРОСМОТР(A1)', [], 'fully non-ASCII (localized) name is not guessed at'],

  /* --- names with dots and digits --- */
  ['=NORM.S.DIST(1,TRUE)', ['NORM.S.DIST'], 'two dots in the name'],
  ['=LOG10(100)', ['LOG10'], 'trailing digits'],
  ['=ATAN2(1,1)', ['ATAN2'], 'trailing digit'],
  ['=DAYS360(A1,B1)', ['DAYS360'], 'trailing digits + refs'],
  ['=IMLOG2(1)', ['IMLOG2'], 'engineering function with a digit'],
  ['=BIN2DEC(101)', ['BIN2DEC'], 'digit in the middle of the name'],
  ['=CEILING.PRECISE(A1,1)+FLOOR.MATH(B1)', ['CEILING.PRECISE', 'FLOOR.MATH'], 'two dotted names'],

  /* --- legacy / add-in / user-defined: must surface, never crash --- */
  ['=GET.CELL(1,A1)', ['GET.CELL'], 'Excel 4 macro function'],
  ['=EVALUATE("1+1")', ['EVALUATE'], 'Excel 4 EVALUATE with a string argument'],
  ['=MyUDF(A1)', ['MYUDF'], 'VBA user-defined function'],
  ['=_xll.MYFUNC(1)', ['_XLL.MYFUNC'], 'XLL add-in function keeps its prefix'],

  /* --- operators, no functions --- */
  ['=A1^2%', [], 'exponent + percent'],
  ['=-A1', [], 'unary minus'],
  ['=A1<>B1', [], 'not-equal'],
  ['=A1>=B1', [], 'greater-or-equal'],
  ['=(A1+B1)*(C1-D1)', [], 'bare parentheses are not calls'],
  ['=A1&B1&C1', [], 'concatenation only'],

  /* --- R1C1 and array constants --- */
  ['=SUM(R1C1:R3C1)', ['SUM'], 'R1C1-style range'],
  ['=SUM({1,2;3,4})', ['SUM'], 'numeric array constant'],
  ['=INDEX({"a","b"},1)', ['INDEX'], 'text array constant'],

  /* --- degenerate input --- */
  ['', [], 'empty string'],
  ['=', [], 'just an equals sign'],
  ['= ', [], 'equals sign and a space'],
  ['hello world', [], 'plain text, not a formula'],
  ['=SUM(A1:A3', ['SUM'], 'unclosed paren'],
  ['=SUM(A1)&"unterminated', ['SUM'], 'unterminated string literal'],
  ["=SUM('unterminated!A1", ['SUM'], 'unterminated sheet-name quote'],
  ['=((((((((((', [], 'nothing but open parens']
];

console.log('adversarial: shared case table — Migration Audit extractor');
for (const [formula, expected, label] of CASES) {
  let got;
  try { got = X.extractFunctions(formula); }
  catch (e) { got = ['THREW: ' + e.message]; }
  eqSet(got, expected, label);
}

console.log('adversarial: shared case table — checker funcs() from docs/checker.html');
for (const [formula, expected, label] of CASES) {
  let got;
  try { got = checkerFuncs(formula); }
  catch (e) { got = ['THREW: ' + e.message]; }
  eqSet(got, expected, label);
}

console.log('adversarial: the two extractors agree on every case');
{
  const disagreements = CASES.filter(([f]) => {
    try { return norm(X.extractFunctions(f)) !== norm(checkerFuncs(f)); }
    catch { return true; }
  }).map(([f]) => f);
  if (disagreements.length) console.log('       differ on: ' + JSON.stringify(disagreements));
  ok(disagreements.length === 0, 'audit and checker produce identical sets');
}

/* ---------- non-string input must not throw (defensive) ---------- */
console.log('adversarial: non-string input');
for (const bad of [null, undefined, 123, {}]) {
  let got;
  try { got = X.extractFunctions(bad); } catch (e) { got = ['THREW: ' + e.message]; }
  eqSet(got, [], 'audit: ' + String(bad) + ' -> no functions, no throw');
  try { got = checkerFuncs(bad); } catch (e) { got = ['THREW: ' + e.message]; }
  eqSet(got, [], 'checker: ' + String(bad) + ' -> no functions, no throw');
}

/* ---------- pathological length: no quadratic backtracking ---------- */
// 60 nested IFs plus a multi-kilobyte text literal — the literal is what used
// to make the old /NAME\s*\(/ regex backtrack across the whole run of letters.
console.log('adversarial: 8000-char deeply nested formula stays linear');
{
  let long = '=';
  for (let i = 0; i < 60; i++) long += 'IF(A' + i + '>' + i + ',';
  long += '"' + 'x'.repeat(8000 - long.length) + '"';
  for (let i = 0; i < 60; i++) long += ',0)';
  ok(long.length >= 8000, 'test formula is ' + long.length + ' chars');

  const time = (fn) => {
    const t0 = process.hrtime.bigint();
    const r = fn(long);
    return [Number(process.hrtime.bigint() - t0) / 1e6, r];
  };
  const [msA, rA] = time(X.extractFunctions);
  eqSet(rA, ['IF'], 'audit: only IF found in the long formula');
  console.log('       audit extractor: ' + msA.toFixed(2) + ' ms');
  ok(msA < 100, 'audit extractor under 100ms (' + msA.toFixed(2) + ' ms)');

  const [msC, rC] = time(checkerFuncs);
  eqSet(rC, ['IF'], 'checker: only IF found in the long formula');
  console.log('       checker extractor: ' + msC.toFixed(2) + ' ms');
  ok(msC < 100, 'checker extractor under 100ms (' + msC.toFixed(2) + ' ms)');

  // A long run of bare letters outside any literal is the other shape that
  // used to backtrack.
  const runFormula = '=' + 'A'.repeat(20000) + '+SUM(B1:B2)';
  const t0 = process.hrtime.bigint();
  const rr = X.extractFunctions(runFormula);
  const ms = Number(process.hrtime.bigint() - t0) / 1e6;
  eqSet(rr, ['SUM'], '20k-char identifier run: only SUM');
  ok(ms < 100, 'identifier run under 100ms (' + ms.toFixed(2) + ' ms)');
}

/* ================= the .xlsx worksheet path ================= */
// extractSheetFormulas() + extractFunctions() over the <f> element shapes a
// real workbook can contain.
console.log('adversarial: worksheet <f> element shapes');
{
  const sheetXml =
    '<worksheet><sheetData>' +
    // shared-formula master (carries the text) ...
    '<row r="1"><c r="A1"><f t="shared" ref="A1:A3" si="0">SUM(B1:C1)</f><v>1</v></c></row>' +
    // ... and a slave cell with no <f> text at all
    '<row r="2"><c r="A2"><f t="shared" si="0"/><v>2</v></c></row>' +
    // array formula
    '<row r="3"><c r="A3"><f t="array" ref="A3:A3">SUM(IF(B1:B3&gt;0,1,0))</f><v>3</v></c></row>' +
    // data-table formula: attributes only, no text
    '<row r="4"><c r="A4"><f t="dataTable" ref="A4:A4" dt2D="0" dtr="0" r1="B1"/><v>4</v></c></row>' +
    // XML entities in the formula text
    '<row r="5"><c r="A5"><f>IF(A1&lt;B1,&quot;a&amp;b (SUM(&quot;,CONCAT(&quot;x&quot;,&quot;y&quot;))</f><v>5</v></c></row>' +
    // a slave whose master was never seen (malformed producer)
    '<row r="6"><c r="A6"><f t="shared" si="99"/><v>6</v></c></row>' +
    '</sheetData></worksheet>';

  let rows;
  try { rows = X.extractSheetFormulas(sheetXml, 'Sheet1'); }
  catch (e) { rows = null; console.log('       THREW: ' + e.message); }
  ok(rows !== null, 'mixed <f> shapes parse without throwing');

  const byCell = {};
  (rows || []).forEach((r) => { byCell[r.cell] = r; });

  ok(byCell.A1 && byCell.A1.sharedRole === 'master', 'A1 is the shared master');
  eqSet(X.extractFunctions(byCell.A1.formula), ['SUM'], 'A1 master -> SUM');

  ok(byCell.A2 && byCell.A2.sharedRole === 'member', 'A2 is a reconstructed shared member');
  ok(byCell.A2.formula === 'SUM(B2:C2)', 'A2 text shifted to SUM(B2:C2)');
  eqSet(X.extractFunctions(byCell.A2.formula), ['SUM'], 'A2 member -> SUM');

  ok(byCell.A3 && byCell.A3.type === 'array', 'A3 is typed as an array formula');
  eqSet(X.extractFunctions(byCell.A3.formula), ['SUM', 'IF'], 'A3 array -> SUM, IF');

  // Documented limitation: a dataTable <f> carries no formula text (the table
  // is described by attributes), so there is nothing to extract. It must be
  // skipped silently rather than counted or crashing.
  ok(!byCell.A4, 'A4 dataTable cell is skipped (no formula text to extract)');

  ok(!!byCell.A5, 'A5 entity-encoded formula is captured');
  ok(byCell.A5.formula === 'IF(A1<B1,"a&b (SUM(",CONCAT("x","y"))',
    'A5 &lt; &gt; &amp; &quot; entities decoded');
  eqSet(X.extractFunctions(byCell.A5.formula), ['IF', 'CONCAT'],
    'A5 -> IF, CONCAT (the "SUM(" inside the decoded string does not count)');

  ok(byCell.A6 && byCell.A6.sharedRole === 'orphan-member', 'A6 orphan member recorded, not invented');
  eqSet(X.extractFunctions(byCell.A6.formula), [], 'A6 orphan member -> no functions');
}

/* ---------- workbook-level shapes ---------- */
console.log('adversarial: workbook-level shapes');
{
  // Non-ASCII sheet name containing a function-like token and parentheses.
  const wb = '<workbook><sheets>' +
    '<sheet name="Bü(ch)er SUM" sheetId="1" r:id="rId1"/>' +
    '</sheets><definedNames>' +
    '<definedName name="Total">SUM(Sheet1!$A$1:$A$9)</definedName>' +
    '</definedNames></workbook>';
  const rels = '<Relationships><Relationship Id="rId1" Target="worksheets/sheet1.xml"/></Relationships>';
  let sheets;
  try { sheets = X.parseWorkbookSheets(wb, rels); }
  catch (e) { sheets = null; console.log('       THREW: ' + e.message); }
  ok(sheets && sheets.length === 1, 'workbook with definedNames parses to 1 sheet');
  ok(sheets && sheets[0].name === 'Bü(ch)er SUM', 'non-ASCII sheet name preserved verbatim');
  ok(sheets && sheets[0].path === 'xl/worksheets/sheet1.xml', 'sheet path resolved through rels');

  // Documented limitation: defined names are NOT audited — only worksheet
  // cells are. The extractor itself handles their refersTo text correctly, so
  // this stays a wiring question, not a correctness one.
  eqSet(X.extractFunctions('SUM(Sheet1!$A$1:$A$9)'), ['SUM'],
    'a definedName refersTo formula extracts correctly if ever wired in');
}

console.log('\n' + pass + ' passed, ' + fail + ' failed  (adversarial suite)');
process.exit(fail ? 1 : 0);
